/* Exile Catch-Up glossary. Every tappable term on the site.
   Schema: spec 5.5. status and statusNote describe 3.30 only, from sources/3.30.0-patch-notes.txt.
   aliases are exact, case-sensitive strings that the Full notes screen auto-links. */
EXILE.addTerms({

  /* Leagues and modes */

  "covens-of-umbra": { name: "Covens of Umbra", kind: "league", status: "new",
    statusNote: "New in 3.30. It is this patch's challenge league.", aliases: ["Coven", "Covens"],
    def: "The 3.30 league. Covenites, members of the Coven, hold rites to summon their Queen. Stop a rite to pick a Fate for the area's boss, making it harder and richer. Its remains, Viscera, go on your Wickerman figure for bonuses." },
  "challenge-league": { name: "Challenge league", kind: "league", status: "unchanged",
    statusNote: "Covens of Umbra is the 3.30 challenge league.", aliases: ["Challenge League", "challenge league", "challenge leagues"],
    def: "A fresh season where everyone starts over with new characters, a new mechanic and a list of challenges. When it ends, its characters move to Standard, the league that never resets." },
  "challenge": { name: "Challenge", kind: "league", status: "unchanged",
    statusNote: "Covens of Umbra has 40 new challenges, plus 8 in Ruthless.", aliases: ["Challenges", "challenges", "challenge"],
    def: "A goal on each league's checklist, such as beating a certain boss. Finishing enough of them earns cosmetic rewards, like hideout decorations. They are optional." },
  "standard": { name: "Standard", kind: "league", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: [],
    def: "The permanent league that never resets. Characters and items from finished challenge leagues move here when those leagues end." },
  "hardcore": { name: "Hardcore", kind: "league", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: [],
    def: "A mode where dying is final for that league. A Hardcore character that dies moves to the normal version of the league and keeps playing there." },
  "ssf": { name: "Solo Self-Found", kind: "league", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: ["SSF"],
    def: "A mode where you can't trade or group with other players. Everything you use, you find or craft yourself." },
  "ruthless": { name: "Ruthless", kind: "league", status: "unchanged",
    statusNote: "Several 3.30 changes skip Ruthless. The notes say which.", aliases: [],
    def: "A much harsher mode with far fewer item drops and tougher rules. Many patch changes work differently there, or skip it." },

  /* League mechanics and other activities */

  "league-mechanic": { name: "League mechanic", kind: "mechanic", status: "changed",
    statusNote: "Ten of them now need a Thread to appear in your maps.",
    aliases: ["League mechanics", "League Mechanics", "league mechanics", "league mechanic", "Primary League Mechanics", "Primary League mechanics", "Secondary League mechanics", "Tertiary League mechanics", "Core League"],
    def: "A side activity that began as one league's main feature. Once it joins the base game for good, it is called core. Breach, Ritual and Legion are examples." },
  "abyss": { name: "Abyss", kind: "mechanic", status: "changed",
    statusNote: "No longer appears by chance in maps. Use an Abyss Thread.", aliases: ["Abysses"],
    def: "Cracks and pits in the ground that release monsters. It is the main source of Abyssal Jewels, which fit special sockets on some gear. Reworked in 3.29 so the pits start open." },
  "bestiary": { name: "Bestiary", kind: "mechanic", status: "changed",
    statusNote: "Yellow beasts are no longer captured. Use a Bestiary Thread to get it in maps.",
    aliases: ["Einhar", "Beasts", "Beast", "Red Beasts", "Red Beast", "red beasts", "Yellow Beasts", "Yellow beasts", "yellow beasts", "Beastcrafting", "Menagerie"],
    def: "Einhar, a hunter, helps you capture beasts in maps. You sacrifice captured red beasts at his Blood Altar for special crafts, called Beastcrafting. Since 3.30, yellow beasts are only killed." },
  "betrayal": { name: "Betrayal", kind: "mechanic", status: "changed",
    statusNote: "Rewards are reworked, and it needs a Betrayal Thread in maps.", aliases: [],
    def: "A mechanic about the Immortal Syndicate, a gang of rivals. You beat members in maps and decide what happens to each, building up to raids on their hideouts, called Safehouses." },
  "blight": { name: "Blight", kind: "mechanic", status: "changed",
    statusNote: "Needs a Blight Thread in maps. Chest counts now scale with Atlas Drops.",
    aliases: ["Blighted Maps", "Blight Ravaged Maps", "Blighted and Blight Ravaged Maps"],
    def: "A tower-defence mini-game. Monsters walk down lanes toward a pump, and you build towers to stop them. Blighted Maps are whole maps of it." },
  "breach": { name: "Breach", kind: "mechanic", status: "changed",
    statusNote: "No longer appears by chance in maps. Use a Breach Thread.", aliases: ["Breaches"],
    def: "A rift that opens in a map and pours out waves of monsters from an alien world. Killing them earns resources for the Genesis Tree, which grows items." },
  "expedition": { name: "Expedition", kind: "mechanic", status: "changed",
    statusNote: "Gwennen no longer gambles, and it needs an Expedition Thread in maps.",
    aliases: ["Gwennen", "Rog", "Remnant", "Remnants", "Astragali", "Broken Circle Artifacts", "Logbooks", "Logbook"],
    def: "You place explosives to dig up buried chests and monsters. Remnants on the ground make dug-up monsters harder and richer. You spend the special currency you find at traders like Rog and Gwennen." },
  "incursion": { name: "Incursion", kind: "mechanic", status: "changed",
    statusNote: "Big rework: Atziri moves into the Temple, and it needs an Incursion Thread in maps.",
    aliases: ["Incursions", "Temporal Incursions", "Temporal Incursion"],
    def: "Short timed trips into the ancient Vaal past. In each one you fight through a temple room, and your choices build the Temple of Atzoatl, a loot dungeon you explore later." },
  "legion": { name: "Legion", kind: "mechanic", status: "changed",
    statusNote: "No longer appears by chance in maps. Use a Legion Thread.", aliases: [],
    def: "A battle frozen in time. You break monsters out of it and kill them before time runs out. Chests and generals frozen inside hold the best loot." },
  "ritual": { name: "Ritual", kind: "mechanic", status: "changed",
    statusNote: "Needs a Ritual Thread in maps. Vessel slots and reward rerolls change.",
    aliases: ["Rituals", "Tribute", "Omen", "Omens"],
    def: "You activate an altar and fight waves of monsters inside its circle to earn Tribute. You spend Tribute at the altar on rewards, such as Omens, one-use charms that change a later craft." },
  "ultimatum": { name: "Ultimatum", kind: "mechanic", status: "changed",
    statusNote: "Rewards keep improving past round 10. Needs an Ultimatum Thread in maps.", aliases: [],
    def: "A trial in a map. Each round adds a harder rule. After any round you can take the reward or keep going for a better one. It is the only source of Catalysts (jewellery upgrades)." },
  "mirage": { name: "Mirage", kind: "mechanic", status: "changed",
    statusNote: "Now core: Mirages can appear in maps in every league.", aliases: ["Mirages", "Miraged", "Djinn"],
    def: "From the 3.28 league. A Mirage is a copy of the area that you step into to free a trapped Djinn, a spirit. You pick a Wish first, which shapes the loot." },
  "harvest": { name: "Harvest", kind: "mechanic", status: "changed",
    statusNote: "Reworked: no separate area, just Sacred Flora plants in the map.", aliases: ["Horticrafting"],
    def: "A garden mechanic. You kill special monsters to collect Lifeforce, a crafting resource, then spend it at the Horticrafting Station on strong crafts, like changing one resistance into another." },
  "delve": { name: "Delve", kind: "mechanic", status: "changed",
    statusNote: "Its Atlas passives are removed, and Sulphite now comes from set maps.", aliases: ["Sulphite"],
    def: "An endless underground mine. A cart lights your way through the dark, and it runs on Sulphite, a fuel you collect from deposits in maps." },
  "heist": { name: "Heist", kind: "mechanic", status: "changed",
    statusNote: "Its Atlas passives are removed, and Whakano now sells jobs for Gold.",
    aliases: ["Heists", "Rogue Markers", "Rogue Marker"],
    def: "Robbing places with a crew of hired thieves called rogues. Contracts are short jobs and Blueprints are big ones. Rogue Markers are Heist's own coins." },
  "delirium": { name: "Delirium", kind: "mechanic", status: "changed",
    statusNote: "In high maps the fog spreads faster, lasts longer and gives more rewards.",
    aliases: ["Delirious", "Mirrors of Delirium", "Mirror of Delirium"],
    def: "Touch a mirror in a map and a fog spreads. Monsters in the fog are harder and drop more, and rewards build up the longer you stay in it." },
  "beyond": { name: "Beyond", kind: "mechanic", status: "changed",
    statusNote: "A new Demonic Evocator can start it, and Beyond bosses now grant Demonic Power.",
    aliases: ["Demonic Power", "K'Tash's Magnificence", "Ghorr's Magnificence", "Beidat's Magnificence"],
    def: "Killing monsters close together can open portals that let demons from Beyond into the map. Beating a Beyond boss can grant Demonic Power, a strong buff for 60 seconds." },
  "strongbox": { name: "Strongbox", kind: "mechanic", status: "changed",
    statusNote: "Better contents, and the monsters they spawn can be magic or rare.", aliases: ["Strongboxes"],
    def: "A locked chest in a map. Opening it spawns waves of guards, and its random bonus lines change what's inside." },
  "shrine": { name: "Shrine", kind: "mechanic", status: "changed",
    statusNote: "Covetous Shrines now spawn on their own, and Gloom and Resonating Shrines are more common.", aliases: ["Shrines"],
    def: "A small monument in a map. Touch it for a short, strong buff (a temporary bonus), such as extra speed or damage." },
  "rogue-exile": { name: "Rogue Exile", kind: "mechanic", status: "changed",
    statusNote: "More rarity and experience. Gigantic ones now pass all their powers to their split clones.",
    aliases: ["Rogue Exiles", "Gigantic Rogue Exile", "Gigantic Rogue Exiles", "Exceptional Rogue Exiles"],
    def: "A hostile copy of a player character, with a full build of gear and skills. It acts as a tough mini-boss in maps and drops good loot." },
  "tormented-spirit": { name: "Tormented Spirit", kind: "mechanic", status: "changed",
    statusNote: "Tormented Heretics now spawn in maps and drop Threads.",
    aliases: ["Tormented Spirits", "Tormented Heretics", "Torment"],
    def: "A ghost that drifts around a map and possesses monsters, making them stronger and adding to their loot." },
  "ore-deposit": { name: "Ore Deposit", kind: "mechanic", status: "changed",
    statusNote: "Deposits give 50% more Ore, and Verisium and Amber now grant buffs.",
    aliases: ["Ore Deposits", "Ore", "Ores", "Verisium Outcrop", "Verisium Ore", "Petrified Amber"],
    def: "A rock in a map you mine for Ore, which you ship from Kingsmarch, the town from the 3.25 league. Some kinds, like Verisium, start a monster fight while you mine them." },
  "sentinel": { name: "Sentinel", kind: "mechanic", status: "changed",
    statusNote: "Buried Sentinels can now spawn in maps of any tier.", aliases: ["Sentinels", "Buried Sentinels", "Buried Sentinel"],
    def: "From the 3.18 Sentinel league. A Sentinel empowers monsters, making them tougher and more rewarding. Buried Sentinels, such as Stalker, Pandemonium and Apex, can be found in maps and switched on." },
  "viridian-wildwood": { name: "Viridian Wildwood", kind: "mechanic", status: "changed",
    statusNote: "Can now appear in any map tier, and in two Act 7 areas.", aliases: ["Wildwood Wisps"],
    def: "A dark forest from the 3.23 Affliction league. You enter it from a map and gather Wisps, glowing spirits that then power up the map's monsters for more loot." },
  "demonic-evocator": { name: "Demonic Evocator", kind: "mechanic", status: "new",
    statusNote: "New in 3.30. Maps can now start with one.", aliases: ["Evocator"],
    def: "A new object that can appear at the start of a map. Touch it and monsters can open Beyond portals when they die, letting demons into the map." },
  "smugglers-cache": { name: "Smuggler's Cache", kind: "mechanic", status: "changed",
    statusNote: "Now found in set maps, with more Blueprints and Rogue Markers.", aliases: ["Smuggler's Caches"],
    def: "A hidden stash from Heist, the robbery mechanic, found in maps. It drops Heist items, such as Blueprints (big robbery jobs) and Rogue Markers (Heist coins)." },
  "sacred-flora": { name: "Sacred Flora", kind: "mechanic", status: "new",
    statusNote: "New in 3.30. It replaces the old Harvest garden area.", aliases: ["Sacred Fauna", "Sacred Specimen"],
    def: "The new form of Harvest, the garden mechanic, in maps. Touch one of these plants to spawn monsters that drop Lifeforce, a crafting resource. Clear them and it releases Wisps into the rest of the map." },
  "fate": { name: "Fate", kind: "mechanic", status: "new",
    statusNote: "New in 3.30, the Covens of Umbra league mechanic.", aliases: ["Fates"],
    def: "A 3.30 league choice. When you break a Coven rite, you pick a Fate for the boss of that area. Each Fate has a few effects that make the boss harder and its rewards better." },
  "wish": { name: "Wish", kind: "mechanic", status: "changed",
    statusNote: "Its Sigils get new effects because Djinn Coins are gone.", aliases: ["Wishes", "Djinn wish", "Sigil", "Sigils"],
    def: "Before entering a Mirage, a copy of the area, you pick one of three Wishes that change it and its loot. Each Wish carries Sigils, named bonus effects." },
  "astral-anomaly": { name: "Astral Anomaly", kind: "mechanic", status: "changed",
    statusNote: "Sigils now boost them: more of them, more Gold, or tougher monsters.", aliases: ["Astral Anomalies"],
    def: "A source of extra monsters in Miraged areas, the copied areas you enter through a Mirage. Sigils on the Wish you pick can add more of them, or make their monsters richer." },
  "vaal-side-area": { name: "Vaal Side Area", kind: "mechanic", status: "changed",
    statusNote: "No longer found in maps, and its Atlas passives are removed.",
    aliases: ["Vaal Side Areas", "Vaal side areas", "Corrupted Side Areas"],
    def: "A small optional area off some zones, full of corrupted monsters and Vaal treasure. Since 3.30 they no longer appear in maps." },
  "mercenary": { name: "Mercenary", kind: "mechanic", status: "changed",
    statusNote: "Weaker attacks and defence at high levels, and new resistance penalties.",
    aliases: ["Mercenaries", "Hired Mercenaries", "Hired Mercenary"],
    def: "A fighter you meet in areas who challenges you to a duel. Win and they join you as an ally for a while. Core since 3.29." },
  "meta-craft": { name: "Meta-crafting", kind: "mechanic", status: "changed",
    statusNote: "New bench options lock one or two prefixes or suffixes for Divine Orbs.",
    aliases: ["Meta-Crafting", "meta-crafted", "Meta-Modifiers"],
    def: "Crafting bench options that lock part of an item, such as its prefixes (one group of bonuses), so your next craft only changes the rest." },
  "blood-shrine": { name: "Blood Shrine", kind: "mechanic", status: "changed",
    statusNote: "You can now cancel its buff, and it lasts between areas.", aliases: ["Blood Shrines"],
    def: "A kind of shrine, a monument you touch for a short buff. The 3.30 notes list Blood Shrines under Ritual. Blood Shrine of Crows, for one, turns some damage you take into chaos damage but adds chaos resistance." },
  "deified": { name: "Deified", kind: "mechanic", status: "new",
    statusNote: "New in 3.30. A Divine Vessel adds it to a map.",
    aliases: ["Deify", "Deified Areas", "Deified areas", "Deified Enchantment Modifier"],
    def: "A map bonus line added by using a Divine Vessel on the map. Its bosses get much stronger and drop better loot, and some can fill a Vessel with their soul to upgrade your Pantheon, your set of god powers." },

  /* Systems */

  "atlas": { name: "Atlas", kind: "system", status: "changed",
    statusNote: "31 maps return to the Atlas and 31 leave.", aliases: ["Atlas of Worlds"],
    def: "The endgame world map. Each spot on it is a map area you can run. Its four corners are called quadrants." },
  "atlas-passive-tree": { name: "Atlas Passive Tree", kind: "system", status: "changed",
    statusNote: "Fully rebuilt: you start in the centre, with up to 150 points.",
    aliases: ["Atlas Passive", "Atlas Passives", "Atlas Passive Skill", "Atlas Passive Skill Points", "Atlas Skill points", "Atlas Skill Points", "Atlas tree", "Core Atlas Passive Tree"],
    def: "A second skill tree for the endgame. Its points change what appears in your maps and what drops there. It barely affects your character's own power." },
  "map-device": { name: "Map Device", kind: "system", status: "changed",
    statusNote: "Threads now go in it where Scarabs used to.", aliases: ["Map device"],
    def: "The portal machine in your hideout. Put a map in it, plus extras like Threads or fragments, to open portals to that area." },
  "shaped-region": { name: "Shaped Region", kind: "system", status: "changed",
    statusNote: "Fully reworked: ten types, one per Thread, giving maps free Threads.", aliases: ["Shaped Regions"],
    def: "A zone of maps on your Atlas tied to one Thread type (Threads add league mini-games). Maps inside start with free Threads of that type, and each objective you clear adds one more." },
  "atlas-anomaly": { name: "Atlas Anomaly", kind: "system", status: "changed",
    statusNote: "Fewer appear if you leave monsters alive. Templar Vaults are now Anomalies.",
    aliases: ["Atlas Anomalies", "Forgotten Shrine"],
    def: "A one-off place that can appear on your Atlas after you finish a map. You enter it for free, with no map item. It started in 3.29." },
  "templar-vault": { name: "Templar Vault", kind: "system", status: "changed",
    statusNote: "No longer from Eagon. It is now an Atlas Anomaly after top Eldritch boss kills.", aliases: ["Templar Vaults"],
    def: "A reward area tied to one corner of the Atlas. You once reached it by clearing a Shaped Region. Since 3.30 it is an Atlas Anomaly, a free one-off area, that can appear after you kill a top Eldritch boss." },
  "memory-trace": { name: "Memory Trace", kind: "system", status: "changed",
    statusNote: "Renamed from Memory Threads. Its altars give less rarity.",
    aliases: ["Memory Traces", "Memory Threads", "Memory Thread", "Memory Altar"],
    def: "A chain of maps on the Atlas leading to an Incarnation, a hard endgame boss. Altars at the end of these maps offer bonuses. Called Memory Threads before 3.30." },
  "voidstone": { name: "Voidstone", kind: "system", status: "changed",
    statusNote: "The Originator Voidstone no longer adds Memory Strands to drops.", aliases: ["Voidstones", "Originator Voidstone"],
    def: "A stone you earn from top endgame bosses and slot into a corner of the Atlas. It raises maps there to tier 16 and adds a bonus to all maps." },
  "eldritch-altar": { name: "Eldritch Altar", kind: "system", status: "changed",
    statusNote: "Altars can now make bosses drop Threads, and their rarity bonuses are lower.",
    aliases: ["Eldritch Altars", "Searing Exarch Altars", "Eater of Worlds Altars"],
    def: "An altar in your maps linked to the Searing Exarch or Eater of Worlds, two top bosses. Each offers a deal: harder monsters or bosses in return for a bonus, like extra drops." },
  "originator": { name: "Originator", kind: "system", status: "changed",
    statusNote: "Rarity on its map modifiers is lowered by about 40 to 50%.", aliases: [],
    def: "A mysterious being behind the Atlas's memory story, from 3.26. Originator-influenced maps are tougher maps whose items often drop with Memory Strands, a property that helps crafting." },
  "kingsmarch": { name: "Kingsmarch", kind: "system", status: "changed",
    statusNote: "Shipping ores and bars now returns only rarer currency.", aliases: [],
    def: "A port town you build up, from the 3.25 Settlers of Kalguur league. Your workers mine and farm, and you ship goods to faraway ports for rewards." },
  "wickerman": { name: "Wickerman", kind: "system", status: "new",
    statusNote: "New in 3.30, part of Covens of Umbra.", aliases: [],
    def: "Your 3.30 league figure. Place Viscera, the remains of bosses you made harder with Fates, on it to gain a scrap of their power. Pre-launch pages list four slots: head, torso, arm and leg." },
  "stash-tab": { name: "Stash Tab", kind: "system", status: "changed",
    statusNote: "The Fragment tab gets a Threads section, and some items move between tabs.",
    aliases: ["Stash Tabs", "Currency Stash Tab", "Fragment Stash Tab", "Essence Stash Tab", "Ultimatum Stash Tab", "Unique Stash Tab"],
    def: "A page of your stash, your shared storage box. Special tabs, like the Currency or Fragment tab, have a fixed slot for each kind of item." },
  "currency-exchange": { name: "Currency Exchange", kind: "system", status: "changed",
    statusNote: "Five Mirage items join it, and Orbs of Chance cost a higher Gold fee.", aliases: [],
    def: "An in-game market where you post offers to swap one currency for another with other players. Each trade costs a Gold fee." },
  "crafting-bench": { name: "Crafting Bench", kind: "system", status: "changed",
    statusNote: "New meta-crafting and white socket options. Recipes move to Nightmare Maps.",
    aliases: ["crafting bench", "Crafting Recipes", "Crafting Recipe"],
    def: "A workbench in your hideout and towns. You pay currency to add a chosen bonus to an item or run a set craft. You unlock options by finding recipes." },
  "vendor-recipe": { name: "Vendor recipe", kind: "system", status: "changed",
    statusNote: "Several recipes change. Two same-name rares now give a Chaos Orb.",
    aliases: ["Vendor Recipe", "Vendor Recipes", "Vendoring", "vendored"],
    def: "Selling a set combination of items to a vendor for a set reward. For example, since 3.30 two rare items with the same name give a Chaos Orb." },
  "recombinator": { name: "Recombinator", kind: "system", status: "changed",
    statusNote: "The result now keeps the item level of the base you pick.", aliases: ["Unpredictable Recombination"],
    def: "A device that merges two items of the same kind into one. The new item keeps a random mix of their bonuses, and you choose which base it uses." },
  "temple-of-atzoatl": { name: "Temple of Atzoatl", kind: "system", status: "changed",
    statusNote: "Atziri moves in, and many rooms and rewards change.",
    aliases: ["Temples of Atzoatl", "Incursion Temple", "Temple Room", "Temple Rooms", "Temple Modifiers", "Glittering Halls", "Jeweller's Workshop", "Jewellery Forge", "Storm of Corruption", "Corruption Chamber", "Catalyst of Corruption", "Locus of Corruption", "Breach Containment Chamber", "House of the Others", "Sanctum of Unity", "Temple Nexus", "Apex of Ascension", "Surveyor's Study", "Office of Cartography", "Museum of Artefacts", "Royal Forge", "Grand Reactor", "Omnitect Forge", "Omnitect Reactor Plant"],
    def: "The ancient Vaal temple you build up through Incursions, timed trips to its past. Each room adds a bonus. Once it's open you explore it for loot, and since 3.30 Atziri waits inside." },
  "cradle-of-creation": { name: "Cradle of Creation", kind: "system", status: "changed",
    statusNote: "New name for the Throne of Atziri. It now brings Uber Atziri and area level 84.", aliases: ["Throne of Atziri"],
    def: "A top room in the Temple of Atzoatl, once called the Throne of Atziri. With it, the Temple is area level 84, holds a harder Atziri, and is tougher and richer throughout." },
  "altar-of-corruption": { name: "Altar of Corruption", kind: "system", status: "changed",
    statusNote: "Now corrupts a corrupted item a second time, and can destroy it.", aliases: [],
    def: "A device in the Temple of Atzoatl. Since 3.30 it corrupts an already-corrupted item again, adding a second risky, permanent change. Some results destroy the item." },
  "altar-of-sacrifice": { name: "Altar of Sacrifice", kind: "system", status: "changed",
    statusNote: "A valuable unique can now give several uniques. It no longer transforms Temple-only uniques.", aliases: [],
    def: "An altar in the Apex of Ascension, a top room of the Temple of Atzoatl. Sacrifice a unique item there to get a random unique of the same kind. It once also used Vials to upgrade certain uniques." },
  "pantheon": { name: "Pantheon", kind: "system", status: "unchanged",
    statusNote: "Divine Vessels now Deify maps, where you capture boss souls for it.", aliases: ["Pantheon powers"],
    def: "A set of god powers you unlock in the campaign. You pick one major and one minor god for a lasting defence bonus, and upgrade them with the souls of certain bosses, caught in a Divine Vessel." },
  "lapidary-lens": { name: "Lapidary Lens", kind: "system", status: "changed",
    statusNote: "Now corrupts a corrupted gem or item a second time, and can destroy it.", aliases: [],
    def: "A device in the Temple of Atzoatl, known for gems. Since 3.30 it corrupts an already-corrupted gem or item again, adding a second risky, permanent change. It can destroy the item." },
  "genesis-tree": { name: "Genesis Tree", kind: "system", status: "changed",
    statusNote: "Its gear passives are weaker, and Lavish Wombgifts give only valuable currency.",
    aliases: ["Genesis Equipment Tree", "Wombgifts", "Wombgift"],
    def: "A Breach tree from the 3.27 league. You feed it Wombgifts, seed-like items, and they birth currency, uniques or gear. Its passive points shape what you get." },
  "passive-skill-tree": { name: "Passive Skill Tree", kind: "system", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: ["Passive Tree", "passive tree", "Passive Skills", "Passive Skill"],
    def: "The big web of bonuses you choose from as you level, gaining about one point per level. Jewels slot into sockets on it for more bonuses." },
  "keyword": { name: "Keyword", kind: "system", status: "changed",
    statusNote: "More item and passive effects are keyworded. Hold Alt to pin some.", aliases: ["Keywords", "keywords", "keyworded"],
    def: "A highlighted word in a tooltip. Hover over it to see what it means. Added in 3.29, borrowed from Path of Exile 2." },

  /* Items */

  "thread": { name: "Thread", kind: "item", status: "new",
    statusNote: "New in 3.30. Threads replace Scarabs.",
    aliases: ["Threads", "Abyss Thread", "Bestiary Thread", "Betrayal Thread", "Blight Thread", "Breach Thread", "Expedition Thread", "Incursion Thread", "Legion Thread", "Ritual Thread", "Ultimatum Thread", "Ritual Threads", "Incursion Threads", "Ultimatum Threads"],
    def: "Replaces the Scarab. Put Threads in the Map Device (your portal machine) to add one league mechanic, an old league's mini-game, to your map. Each Thread you spend, up to eight, raises the chance of strong random twists to it." },
  "scarab": { name: "Scarab", kind: "item", status: "removed",
    statusNote: "Removed in 3.30. Threads replace it.", aliases: ["Scarabs", "Veiled Scarabs", "Veiled Scarab"],
    def: "An item you placed in the Map Device next to your map to add or boost one kind of extra content. Gone in 3.30, and old ones became Threads." },
  "frayed-thread": { name: "Frayed Thread", kind: "currency", status: "new",
    statusNote: "New in 3.30. Old Veiled Scarabs became these.", aliases: ["Frayed Threads"],
    def: "A new currency. Use it, or sell it to a vendor, to get a random Thread, the item that adds a league mini-game to your map." },
  "map": { name: "Map", kind: "item", status: "changed",
    statusNote: "31 maps return to the Atlas and 31 leave in 3.30.", aliases: ["Maps", "Map item", "Map items", "Map Item", "Map Items"],
    def: "An endgame item you put in the Map Device to open an area. Since 3.28 a map item only has a tier (difficulty), and you pick the area on your Atlas." },
  "unique-map": { name: "Unique Map", kind: "item", status: "changed",
    statusNote: "No longer holds Crafting Recipes, and Kirac sells them more often.", aliases: ["Unique Maps"],
    def: "A one-of-a-kind map with its own name, layout and modifiers. Clearing them earns Atlas passive points, up to a limit." },
  "nightmare-map": { name: "Nightmare Map", kind: "item", status: "changed",
    statusNote: "All meta-crafting recipes now drop here, and rarity bonuses are lower.", aliases: ["Nightmare Maps", "Nightmare"],
    def: "The hardest maps, tier 17. They can drop once you have a Voidstone, a stone from top bosses, and each one you clear gives an Atlas passive point." },
  "fragment": { name: "Fragment", kind: "item", status: "changed",
    statusNote: "Shaper, Elder and Conqueror Fragments no longer add Item Quantity or get used up with a map.",
    aliases: ["Fragments", "Map Fragments", "Map Fragment"],
    def: "A piece you put in the Map Device, alone or with a map. Some open boss fights, and others add bonuses to the map." },
  "vaal-fragment": { name: "Vaal Fragment", kind: "item", status: "removed",
    statusNote: "Removed. Mortal Fragments become Royal Visages, and Sacrifice Fragments do nothing.",
    aliases: ["Vaal Fragments", "Sacrifice Fragments", "Sacrifice Fragment", "Mortal Fragments", "Mortal Fragment", "Sacrifice and Mortal Fragments", "Sacrifice or Mortal Fragments"],
    def: "Sacrifice and Mortal Fragments, used in the Map Device to reach Atziri, the Vaal queen. Removed in 3.30: Mortal ones turn into Royal Visages, and Sacrifice ones stay but do nothing." },
  "maven-invitation": { name: "Maven Invitation", kind: "item", status: "changed",
    statusNote: "Bosses killed inside can't spawn Templar Vaults, and two give fewer fractured items.",
    aliases: ["Maven Invitations", "Invitations", "Invitation"],
    def: "An item from Kirac, the endgame helper, that opens a fight against several bosses the Maven has collected. The Maven is a top endgame boss." },
  "valdo-map": { name: "Valdo's Map", kind: "item", status: "changed",
    statusNote: "69 more map options, and its rewards now drop unidentified.",
    aliases: ["Valdo Maps", "Valdo Map", "Valdo's Puzzle Box"],
    def: "A special tier 17 map that comes from Valdo's Puzzle Box. It has tough extra rules, and clearing it pays out the shiny 'foil' unique item it promises." },
  "voidborn-reliquary": { name: "Voidborn Reliquary", kind: "item", status: "changed",
    statusNote: "96 more possible rewards, and they now drop unidentified.",
    aliases: ["Voidborn Reliquary Keys", "Voidborn Reliquary Key"],
    def: "A special area opened with a Voidborn Reliquary Key. Its reward is a shiny 'foil' unique item." },
  "black-barya": { name: "Black Barya", kind: "item", status: "changed",
    statusNote: "Now on the Atlas in every league, at area level 84.", aliases: ["The Black Barya"],
    def: "A key item from the 3.28 Mirage league. It opens the Black Barya, where you fight Saresh, that league's undead-raising villain." },
  "unique-item": { name: "Unique item", kind: "item", status: "changed",
    statusNote: "11 new uniques, and several old ones change.",
    aliases: ["Unique Item", "Unique Items", "Unique items", "Uniques", "Unique"],
    def: "An item with an orange name and a fixed set of special bonuses, often ones no other item has. Builds are often made around one." },
  "jewel": { name: "Jewel", kind: "item", status: "changed",
    statusNote: "3.30 adds a new jewel base, the Mycelium Core.", aliases: ["Jewels"],
    def: "A small item you slot into a jewel socket on your passive skill tree to get extra bonuses." },
  "abyssal-jewel": { name: "Abyssal Jewel", kind: "item", status: "changed",
    statusNote: "Merrick's Ducat now works on them directly, outside Allflame Crafting.", aliases: ["Abyssal Jewels"],
    def: "A jewel that drops from Abyss. It fits Abyssal sockets on some gear, such as the Stygian Vise belt, and also fits the passive tree." },
  "cluster-jewel": { name: "Cluster Jewel", kind: "item", status: "changed",
    statusNote: "Drops more from Delirium. Some speed bonuses can no longer stack on one jewel.", aliases: ["Cluster Jewels"],
    def: "A big jewel for the outer sockets of your passive skill tree. It grows a small new branch of passive skills there." },
  "timeless-jewel": { name: "Timeless Jewel", kind: "item", status: "changed",
    statusNote: "One of them, Heroic Tragedy, changes in 3.30.", aliases: ["Timeless Jewels"],
    def: "A unique jewel that rewrites the passive skills around it into themed ones from an old faction, such as the Kalguur or the Vaal." },
  "mycelium-core": { name: "Mycelium Core", kind: "item", status: "new",
    statusNote: "New jewel base in 3.30.", aliases: [],
    def: "A new kind of jewel base added in 3.30. A jewel is a small item you slot into your passive skill tree for extra bonuses." },
  "heroic-tragedy": { name: "Heroic Tragedy", kind: "item", status: "changed",
    statusNote: "Some passives are weaker, and it now drops from Olroth.", aliases: [],
    def: "A unique jewel from the 3.28 Mirage league. It rewrites nearby passive skills into Kalguuran ones, many built around Ward, a layer that soaks damage from hits." },
  "divination-card": { name: "Divination Card", kind: "item", status: "changed",
    statusNote: "Several are disabled, and league-only rewards are removed.", aliases: ["Divination Cards"],
    def: "A collectible card. Gather a full set and trade it in for the reward shown on it, often a specific unique item or currency." },
  "tincture": { name: "Tincture", kind: "item", status: "changed",
    statusNote: "Living Blade now allows 2 extra active Tinctures, up from 1, and Warden passives change.", aliases: ["Tinctures"],
    def: "A flask-like item you switch on to boost your weapon attacks. While it runs, Mana Burn drains your mana faster and faster, and it switches off when your mana runs out." },
  "talisman": { name: "Talisman", kind: "item", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: ["Talismans"],
    def: "An amulet type tied to beasts. Since 3.29 talismans drop from red beasts and Bestiary bosses, each tied to one beast, and carry special enchantment bonuses." },
  "blueprint": { name: "Blueprint", kind: "item", status: "changed",
    statusNote: "More drop from Smuggler's Caches and Contracts, and Whakano can sell them.",
    aliases: ["Blueprints", "Heist Blueprints", "Heist Blueprint"],
    def: "An item for a big Heist robbery with several wings. Before you go in, you pay Rogue Markers to reveal more wings and rewards." },
  "contract": { name: "Contract", kind: "item", status: "changed",
    statusNote: "No longer in the core drop pool. Whakano sells them for Gold.",
    aliases: ["Contracts", "Heist Contracts", "Heist Contract"],
    def: "An item that starts a short Heist robbery with one main target. Blueprints are the bigger, multi-part version." },
  "rogue-equipment": { name: "Rogue Equipment", kind: "item", status: "changed",
    statusNote: "Its rarity and quantity bonuses are lowered or removed.",
    aliases: ["Heist Equipment", "Trinket", "Trinkets", "Brooch", "Brooches", "Heist Rogue Brooches and Trinkets", "Heist Trinket and Brooch"],
    def: "Gear for the thieves you hire in Heist, such as Trinkets and Brooches. It changes what your robberies reward and how your thieves work." },
  "incubator": { name: "Incubator", kind: "item", status: "removed",
    statusNote: "The last Mirage Incubators stop dropping. Old ones give new rewards.", aliases: ["Incubators"],
    def: "An item you attach to gear. Kill enough monsters while wearing it and it drops a reward. They no longer drop in 3.30." },
  "vial": { name: "Vial", kind: "item", status: "removed",
    statusNote: "Vials stop dropping and no longer work. Their uniques drop in the Temple instead.", aliases: ["Vials", "Vial of Fate"],
    def: "An item once used at an altar in the Temple of Atzoatl to turn certain unique items into upgraded versions. In 3.30 Vials stop dropping and do nothing." },
  "viscera": { name: "Viscera", kind: "item", status: "new",
    statusNote: "New in 3.30, part of Covens of Umbra.", aliases: [],
    def: "Boss remains from the 3.30 league. A boss powered up by Fates can drop its Viscera. Put Viscera on your Wickerman figure to gain part of that boss's power." },
  "flask": { name: "Flask", kind: "item", status: "unchanged",
    statusNote: "No broad change. Some Pathfinder flask passives change.", aliases: ["Flasks", "Life Flask"],
    def: "A refillable potion on your belt, with room for five. Life and mana flasks heal you, and utility flasks give a short buff. Killing monsters refills their charges." },
  "blood-filled-vessel": { name: "Blood-Filled Vessel", kind: "item", status: "changed",
    statusNote: "Now needs Ritual Threads on the map: 2 slots at 4 Threads, 3 slots at 8.", aliases: ["Blood-Filled Vessels", "Blood-filled Vessel"],
    def: "A Ritual item that stores the monsters from a finished Ritual altar. Put it in the Map Device with a map to add those monsters to a Ritual in that map." },
  "audience-with-the-king": { name: "Audience with the King", kind: "item", status: "changed",
    statusNote: "Rerolling Ritual rewards no longer always offers one, but always offers an Omen.", aliases: [],
    def: "An item you can buy at Ritual altars with Tribute, Ritual's reward points. Put it in the Map Device to fight the King in the Mists, Ritual's boss." },
  "mercenary-warrant": { name: "Mercenary Warrant", kind: "item", status: "changed",
    statusNote: "No longer used with a map. It now opens the Proving Grounds for a rematch.",
    aliases: ["Mercenary Warrants", "Warrant", "Warrants", "Proving Grounds"],
    def: "A promise from a Mercenary, a fighter you can hire, to duel you again later. Since 3.30 it opens the Proving Grounds, an Atlas area for the rematch. Players can trade Warrants." },
  "enshrouding-crystal": { name: "Enshrouding Crystal", kind: "item", status: "changed",
    statusNote: "A new Afarud Enshrouding Crystal works on unique quivers.",
    aliases: ["Enshrouding Crystals", "Enshroud", "Enshrouded"],
    def: "A 3.29 currency that enshrouds a unique item. Charge it up in Legion's frozen-battle area and it turns into a different unique of the same kind." },
  "veiled-item": { name: "Veiled item", kind: "item", status: "changed",
    statusNote: "No longer a reward outside Betrayal.",
    aliases: ["Veiled Items", "Veiled items", "Veiled Exalted Orbs", "Veiled Chaos Orbs", "Veiled Modifier"],
    def: "An item with a hidden 'veiled' bonus from Betrayal. Unveiling it lets you pick one of a few new bonuses. Veiled Chaos and Exalted Orbs are currencies that give an item one." },

  /* Currency */

  "orb-of-transmutation": { name: "Orb of Transmutation", kind: "currency", status: "changed",
    statusNote: "Vendors now sell it for an Orb of Augmentation.", aliases: ["Orbs of Transmutation"],
    def: "Turns a plain white item into a blue (magic) item with one or two random bonuses." },
  "orb-of-augmentation": { name: "Orb of Augmentation", kind: "currency", status: "changed",
    statusNote: "Vendors now sell an Orb of Transmutation for one.", aliases: ["Orbs of Augmentation"],
    def: "Adds a second random bonus to a blue (magic) item that has only one. A cheap, common crafting orb." },
  "regal-orb": { name: "Regal Orb", kind: "currency", status: "unchanged",
    statusNote: "No change to the orb. A vendor recipe that gave one now gives an Exalted Orb.", aliases: ["Regal Orbs"],
    def: "Upgrades a blue (magic) item to a yellow (rare) one, keeping its bonuses and adding one more." },
  "orb-of-regret": { name: "Orb of Regret", kind: "currency", status: "changed",
    statusNote: "A Bestiary recipe that made Orbs of Binding now makes 2 of these.", aliases: ["Orbs of Regret"],
    def: "Gives you one refund point, to take back a point you spent on your passive skill tree." },
  "portal-scroll": { name: "Portal Scroll", kind: "currency", status: "changed",
    statusNote: "Monsters with high Item Rarity drop fewer, and Transmutation orbs no longer cost them.", aliases: ["Portal Scrolls"],
    def: "Opens a portal back to town from wherever you are. Vendors also take them as cheap payment." },
  "orb-of-alteration": { name: "Orb of Alteration", kind: "currency", status: "changed",
    statusNote: "Replaces Orbs of Chance in many bench and vendor costs.", aliases: ["Orbs of Alteration"],
    def: "Rerolls the random bonuses on a blue (magic) item. A cheap, common crafting orb." },
  "orb-of-alchemy": { name: "Orb of Alchemy", kind: "currency", status: "changed",
    statusNote: "More common now that Orbs of Binding are gone, and it replaces Orbs of Chance in several costs.", aliases: ["Orbs of Alchemy"],
    def: "Turns a plain white item into a yellow (rare) item with several random bonuses." },
  "chaos-orb": { name: "Chaos Orb", kind: "currency", status: "changed",
    statusNote: "Two rare items with the same name now sell for one.", aliases: ["Chaos Orbs"],
    def: "Rerolls all the random bonuses on a yellow (rare) item. Players also use it as everyday trade money." },
  "exalted-orb": { name: "Exalted Orb", kind: "currency", status: "changed",
    statusNote: "Three rare items with the same name now sell for one.", aliases: ["Exalted Orbs"],
    def: "Adds one new random bonus to a yellow (rare) item that has room for it." },
  "divine-orb": { name: "Divine Orb", kind: "currency", status: "changed",
    statusNote: "It pays for the new meta-crafting options.", aliases: ["Divine Orbs"],
    def: "Rerolls the numbers inside an item's random bonuses, keeping the bonuses themselves. Patch notes use it to update old unique items to new values. A top trade currency." },
  "orb-of-scouring": { name: "Orb of Scouring", kind: "currency", status: "changed",
    statusNote: "Vendors now want 4 Orbs of Fusing for it, and it pays for a white-socket craft.", aliases: ["Orbs of Scouring"],
    def: "Removes all random bonuses from an item, turning it back into a plain white item." },
  "orb-of-chance": { name: "Orb of Chance", kind: "currency", status: "changed",
    statusNote: "Much more likely to make a unique, but much rarer, and vendors stop selling it.", aliases: ["Orbs of Chance"],
    def: "Turns a plain white item into a random rarity, with a chance to make it a unique (orange) item." },
  "orb-of-binding": { name: "Orb of Binding", kind: "currency", status: "removed",
    statusNote: "No longer drops. Old ones still work.", aliases: ["Orbs of Binding"],
    def: "Turned a plain white item into a yellow (rare) item with linked sockets. It stops dropping in 3.30, though old ones still work." },
  "blessed-orb": { name: "Blessed Orb", kind: "currency", status: "changed",
    statusNote: "Updates some reworked base items and pays for meta-crafting.", aliases: ["Blessed Orbs"],
    def: "Rerolls the numbers on an item's built-in bonus, the implicit line above its random bonuses." },
  "sacred-orb": { name: "Sacred Orb", kind: "currency", status: "changed",
    statusNote: "Made more common in 3.30.", aliases: ["Sacred Orbs"],
    def: "Rerolls the base defence numbers on a piece of armour, like its Armour or Energy Shield value." },
  "ancient-orb": { name: "Ancient Orb", kind: "currency", status: "changed",
    statusNote: "Riker's Betrayal reward now gives chests of them.", aliases: ["Ancient Orbs"],
    def: "Turns a unique (orange) item into a random different unique of the same kind, such as another unique sword." },
  "vaal-orb": { name: "Vaal Orb", kind: "currency", status: "changed",
    statusNote: "Its vendor recipe now takes 5 Vaal skill gems. Djinn-Touched ones make items Twice Corrupted.", aliases: ["Vaal Orbs"],
    def: "Corrupts an item with an unpredictable result, good or bad. After that, most crafting can no longer change the item." },
  "volatile-vaal-orb": { name: "Volatile Vaal Orb", kind: "currency", status: "changed",
    statusNote: "Beyond monsters inside a Mirage no longer drop them.", aliases: ["Volatile Vaal Orbs"],
    def: "A risky orb for unique items. It either rerolls the numbers on some of the item's bonuses, which can go past their normal range, and corrupts it, or it destroys the item." },
  "tainted-currency": { name: "Tainted currency", kind: "currency", status: "changed",
    statusNote: "Beyond monsters now drop it more often.", aliases: ["Tainted Currency"],
    def: "A family of orbs, such as the Tainted Chaos Orb, that work only on corrupted items (items locked by a Vaal Orb). They can still change those items, often with a risk. Beyond demons drop them." },
  "chromatic-orb": { name: "Chromatic Orb", kind: "currency", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: ["Chromatic Orbs"],
    def: "Rerolls the colours of an item's sockets, the slots for gems. Since 3.29 any gem fits any socket, and a matching colour only adds a little quality." },
  "mirror-of-kalandra": { name: "Mirror of Kalandra", kind: "currency", status: "changed",
    statusNote: "Can't be used on items that can be modified while corrupted.", aliases: ["Mirrors of Kalandra"],
    def: "The rarest currency. It makes a copy of an item, and the copy can never be changed." },
  "scroll-of-wisdom": { name: "Scroll of Wisdom", kind: "currency", status: "changed",
    statusNote: "Every town vendor sells it for 15 Gold, and richer monsters drop fewer.", aliases: ["Scrolls of Wisdom"],
    def: "Identifies an item, showing its hidden random bonuses so you can use or sell it." },
  "catalyst": { name: "Catalyst", kind: "currency", status: "changed",
    statusNote: "Dextral and Sinistral Catalysts join the Currency Exchange.",
    aliases: ["Catalysts", "Dextral Catalyst", "Sinistral Catalyst", "Dextral and Sinistral Catalysts"],
    def: "Adds quality to a ring, amulet or belt that boosts one kind of bonus, such as attack or caster bonuses. Only Ultimatum drops them since 3.29." },
  "oil": { name: "Oil", kind: "currency", status: "changed",
    statusNote: "Silver Oil on Blighted Maps now adds rarity, and anointed passives are keyworded.",
    aliases: ["Oils", "Silver Oils", "Oil Extractors", "Anointments", "Anointed", "Anoint"],
    def: "A Blight drop. Three oils together can anoint an amulet, adding a chosen passive skill to it. Oils also add bonuses to Blighted Maps." },
  "essence": { name: "Essence", kind: "currency", status: "changed",
    statusNote: "New Essence of Trickery. Weeping and Wailing Essences leave yellow and red maps.",
    aliases: ["Essences", "Imprisoned Monsters"],
    def: "Monsters trapped in crystals in maps. Free and kill one to get an Essence, a currency that makes an item rare (yellow) with one guaranteed bonus." },
  "mavens-chisel": { name: "Maven's Chisel", kind: "currency", status: "changed",
    statusNote: "The Scarab one now boosts Threads, and Procurement gives less rarity.",
    aliases: ["Maven's Chisels", "Maven's Chisel of Threads", "Maven's Chisel of Scarabs", "Maven's Chisel of Procurement"],
    def: "A map currency that adds quality to a map. Each kind turns that quality into one bonus, such as more Threads found or more Item Rarity (better drops)." },
  "delirium-orb": { name: "Delirium Orb", kind: "currency", status: "changed",
    statusNote: "Now rolls a lasting Delirious modifier on a rare map, stacking up to 100%.",
    aliases: ["Delirium Orbs", "Delirium Orbed"],
    def: "A currency that adds Delirium, a reward fog, to a map. Since 3.30 it adds a lasting bonus line to a yellow (rare) map, and more of one kind stack up to 100%." },
  "divine-vessel": { name: "Divine Vessel", kind: "currency", status: "changed",
    statusNote: "Now a currency that Deifies a map, and it stacks to 20.", aliases: ["Divine Vessels"],
    def: "A currency you use on a map to Deify it, making its boss much stronger and richer. Certain bosses then fill the Vessel, which upgrades your Pantheon, a set of god powers." },
  "allflame-ember": { name: "Allflame Ember", kind: "currency", status: "changed",
    statusNote: "Now a currency used on a map, with three new kinds.", aliases: ["Allflame Embers", "Allflames"],
    def: "A currency you use on a map. It swaps some of the map's monster packs for a themed kind, such as toads, and says how many packs it changes." },
  "royal-visage": { name: "Royal Visage", kind: "currency", status: "new",
    statusNote: "New in 3.30. Old Mortal Fragments become these.", aliases: ["Royal Visages"],
    def: "A new currency Atziri drops in high-level Temples. Use it on a tier 16 map so its Incursions, timed trips to the Vaal past, are Alluring: harder and richer." },
  "soul-core": { name: "Soul Core", kind: "currency", status: "new",
    statusNote: "New in 3.30. Old Coins of Knowledge, Power and Skill became Soul Cores.", aliases: ["Soul Cores"],
    def: "Corrupts a level 20 skill gem and gives it a random support gem effect. Since 3.30 it may give a bad effect instead. Atziri and her Temple drop them." },
  "astrolabe": { name: "Astrolabe", kind: "currency", status: "changed",
    statusNote: "Now adds a Shaped Region around a chosen map, and three types are removed.", aliases: ["Astrolabes"],
    def: "An Atlas currency. Use it on a chosen map to add a Shaped Region of its type there, replacing any other region of that type. Regions give maps free Threads." },
  "refracting-fog": { name: "Refracting Fog", kind: "currency", status: "changed",
    statusNote: "Delirium bosses in tier 14+ maps can now drop it outside a Mirage.", aliases: ["Refracting Fogs"],
    def: "A currency that rerolls the small-passive bonus of a Cluster Jewel, a jewel that adds passive skills to your tree." },
  "gold": { name: "Gold", kind: "currency", status: "changed",
    statusNote: "More things cost Gold, like Scrolls of Wisdom and Whakano's shop.", aliases: [],
    def: "Coins that drop from monsters, added in 3.25. You spend Gold at vendors, in Kingsmarch, on Currency Exchange fees and to reroll shops." },
  "lifeforce": { name: "Lifeforce", kind: "currency", status: "changed",
    statusNote: "Fewer, bigger stacks, and some crafts now cost two colours.", aliases: ["Crystallised Lifeforce"],
    def: "Harvest's crafting resource, in three colours: Wild, Vivid and Primal. You collect it from Harvest monsters and spend it on crafts at the Horticrafting Station." },
  "djinn-coin": { name: "Djinn Coin", kind: "currency", status: "removed",
    statusNote: "Removed from Mirage. Some are deleted, and three became Soul Cores.",
    aliases: ["Djinn Coins", "Coins of Restoration and Desecration", "Coins of Knowledge, Power and Skill", "Coins"],
    def: "Coins from the 3.28 Mirage league that changed gems or items. In 3.30 the Restoration and Desecration coins are deleted, and the Knowledge, Power and Skill coins become Soul Cores." },
  "merricks-ducat": { name: "Merrick's Ducat", kind: "currency", status: "changed",
    statusNote: "Now works on Abyssal Jewels directly, and drops outside Allflame encounters too.", aliases: ["Merrick's Ducats"],
    def: "A Ducat, a currency from the 3.29 league. It adds one more random bonus to a rare Abyssal Jewel, even a full one, then corrupts the jewel so it can't be changed further." },

  /* Item stats and properties */

  "prefix": { name: "Prefix", kind: "stat", status: "changed",
    statusNote: "New bench crafts lock one or two prefixes for Divine Orbs.", aliases: ["Prefixes", "Prefix Modifier", "Prefix Modifiers"],
    def: "One of the two groups of random bonuses on gear. A yellow (rare) item can have up to three prefixes and three suffixes." },
  "suffix": { name: "Suffix", kind: "stat", status: "changed",
    statusNote: "New bench crafts lock one or two suffixes for Divine Orbs.", aliases: ["Suffixes", "Suffix Modifier", "Suffix Modifiers"],
    def: "One of the two groups of random bonuses on gear. A yellow (rare) item can have up to three suffixes and three prefixes." },
  "modifier": { name: "Modifier", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.",
    aliases: ["Modifiers", "modifiers", "modifier", "Explicit Modifiers", "Explicit Modifier", "explicit modifier"],
    def: "One line of random bonus, or penalty, on an item, map or monster. The random ones are called explicit modifiers." },
  "implicit-modifier": { name: "Implicit Modifier", kind: "stat", status: "changed",
    statusNote: "Implicits change on 12 Atlas base items, mostly upward.",
    aliases: ["Implicit Modifiers", "Implicit", "Implicits", "implicit Modifier", "implicit Modifiers", "implicit modifier"],
    def: "A built-in bonus line that comes with the kind of item, shown above its random bonuses. Corruption can add or replace one." },
  "enchantment": { name: "Enchantment", kind: "stat", status: "changed",
    statusNote: "Several map currencies now work by adding a map Enchantment.",
    aliases: ["Enchantments", "Enchantment Modifier", "Enchantment Modifiers", "Enchant"],
    def: "A special bonus line added by a set source, such as a currency. It sits apart from an item's random bonuses. Maps can carry them too." },
  "corrupted": { name: "Corrupted", kind: "stat", status: "changed",
    statusNote: "More ways to make items Twice Corrupted, and new risks of destroying them.",
    aliases: ["Corrupt", "Corruption", "Twice Corrupted"],
    def: "A locked state. Vaal Orbs and some devices corrupt items with random good or bad results, and then most crafting can't change them. Twice Corrupted means corrupted a second time." },
  "quality": { name: "Quality", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: [],
    def: "A percentage, usually up to 20%, on gear, gems and maps. On gear it raises base stats like damage or armour. On gems and maps it adds a bonus." },
  "rarity": { name: "Rarity", kind: "stat", status: "changed",
    statusNote: "How a drop's rarity picks the item changed. See Item Rarity.",
    aliases: ["Rare Monsters", "Rare Monster", "Rare monsters", "Magic Monsters", "Magic Monster", "Magic monsters", "Normal and Magic Monsters", "Unique Monsters", "Unique Monster", "Unique Bosses", "Rare items", "Rare Items", "Rare item", "Rare Item", "Magic items", "Magic Items", "Magic and Rare items", "Rare Maps", "Rare Map", "Magic Maps"],
    def: "How special an item or monster is, shown by name colour: Normal (white), Magic (blue), Rare (yellow) or Unique (orange). Higher rarity means more random bonuses or powers. Item Rarity is a separate bonus." },
  "item-rarity": { name: "Item Rarity", kind: "stat", status: "changed",
    statusNote: "It now decides which kinds of items can drop, so richer monsters drop better currency.",
    aliases: ["Rarity of Items", "Rarity of items", "Rarity of Contained Items"],
    def: "A bonus that makes drops more likely to be better rarities. Since 3.30 it also decides which drop lists a monster picks from, so high-rarity monsters drop better currency." },
  "item-quantity": { name: "Item Quantity", kind: "stat", status: "changed",
    statusNote: "Removed from most monsters and maps. Item Rarity or Atlas Drops replace it.",
    aliases: ["Quantity of Items", "Map Item Quantity"],
    def: "A bonus for more items dropping. 3.30 removes it from most monsters and maps, swapping in Item Rarity or Atlas Drops instead." },
  "atlas-drops": { name: "Atlas Drops", kind: "stat", status: "new",
    statusNote: "New in 3.30. It replaces Item Quantity on maps.", aliases: ["Atlas Drop"],
    def: "A new map bonus that replaces Item Quantity on maps. Each 1% gives 1% more Maps and Threads, plus more league resources like Lifeforce." },
  "item-tier": { name: "Item Tier", kind: "stat", status: "new",
    statusNote: "New in 3.30. Items in Ruthless have no Item Tier.", aliases: ["Item Tiers", "Tiered"],
    def: "A new grade from 2 to 5 that some blue and yellow drops get from Act 6 on. Higher grades mean stronger bonuses and better odds of good bases, quality and sockets." },
  "modifier-tier-rating": { name: "Modifier Tier Rating", kind: "stat", status: "changed",
    statusNote: "Reworked: every bit now helps, and it no longer skews which bonuses appear.", aliases: ["modifier tier rating"],
    def: "A hidden number that pushes an item's random bonuses toward stronger versions when the item is made. Item Tier, the Genesis Tree and some crafts raise it." },
  "item-level": { name: "Item level", kind: "stat", status: "changed",
    statusNote: "Tier 5 drops can get +1 item level, and Recombinator results keep the chosen base's level.",
    aliases: ["item level", "Item Level"],
    def: "A number on every item, set by the level of the area it dropped in. Higher item levels can roll stronger random bonuses." },
  "area-level": { name: "Area level", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: ["area level", "area levels", "Area Level"],
    def: "The level of an area, which sets how strong its monsters are and the item level of its drops. Maps start at area level 68." },
  "map-tier": { name: "Map tier", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: ["Map Tier", "Red Maps", "Red Tier Maps", "Yellow and Red Maps", "high-tier Maps"],
    def: "How hard a map is, from 1 to 16, plus tier 17 Nightmare Maps. Tiers 1 to 5 are white maps, 6 to 10 yellow, and 11 to 16 red." },
  "fractured-item": { name: "Fractured item", kind: "stat", status: "changed",
    statusNote: "Many sources are removed, but tier 5 drops can be fractured.", aliases: ["Fractured", "Fractured Items", "Fractured items"],
    def: "An item with one bonus locked in place, so crafting can never remove or change it. Good fractured bases are prized for crafting." },
  "influence": { name: "Influence", kind: "stat", status: "changed",
    statusNote: "Some currencies and fragments now show an influence background.", aliases: ["Influenced", "influenced"],
    def: "A mark on an item or map from a big endgame power, such as the Shaper or Elder. Influenced gear can roll special bonuses." },
  "memory-strand": { name: "Memory Strand", kind: "stat", status: "changed",
    statusNote: "The Originator Voidstone no longer adds them to drops.", aliases: ["Memory Strands"],
    def: "A property some gear drops with. More Memory Strands push the bonuses you roll on the item toward stronger versions. Originator-influenced maps drop the most." },
  "socket": { name: "Socket", kind: "stat", status: "changed",
    statusNote: "A bench craft now makes all sockets white, and Item Tier affects socket count.",
    aliases: ["Sockets", "White Sockets", "White Socket", "Socket links", "Socket Links"],
    def: "A slot on gear for a gem. Linked sockets let gems work together. Since 3.29 most sockets are white, and any gem fits any socket." },
  "base-type": { name: "Base type", kind: "stat", status: "changed",
    statusNote: "Some bases now drop only at higher Item Tiers, and 11 join the core drop pool.",
    aliases: ["base type", "base types", "basetype", "Base types"],
    def: "The kind of item before any random bonuses, like a Steel Ring. It sets the item's built-in stats and which bonuses it can roll." },
  "drop-pool": { name: "Drop Pool", kind: "stat", status: "changed",
    statusNote: "Item Rarity now decides which drop pools a monster can pick.", aliases: ["Drop Pools", "core drop pool"],
    def: "The list the game picks from when an item drops, like weapons or currency. The core drop pool is everything that can drop anywhere, outside special sources." },
  "unidentified-item": { name: "Unidentified item", kind: "stat", status: "changed",
    statusNote: "Valdo, Voidborn and Vaal Aspect rewards now drop unidentified.",
    aliases: ["Unidentified", "Identified", "identified"],
    def: "An item whose random bonuses are hidden until you read a Scroll of Wisdom on it. Unidentified maps give a small bonus when run." },
  "ailment": { name: "Ailment", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: ["Ailments", "Elemental Ailments", "Freeze", "Shock", "Ignite"],
    def: "A harmful effect from a hit, such as Ignite (burning), Freeze, Shock (taking more damage), Chill (slowing) or Poison." },
  "charge": { name: "Charge", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.",
    aliases: ["Power Charge", "Power Charges", "Frenzy Charge", "Frenzy Charges", "Endurance Charge", "Endurance Charges", "Endurance charges"],
    def: "Stacking buffs. Power Charges add critical strike chance, Frenzy Charges add speed and damage, and Endurance Charges add damage reduction and resistances." },
  "ward": { name: "Ward", kind: "stat", status: "unchanged",
    statusNote: "No broad change. Some Heroic Tragedy Ward passives change.", aliases: [],
    def: "A defence layer that soaks the damage of a hit, then breaks and refills after a short delay. Runic Expedition gear and some passives give it." },
  "light-radius": { name: "Light Radius", kind: "stat", status: "changed",
    statusNote: "Rare gear can now roll up to 30% Light Radius.", aliases: [],
    def: "How far the light around your character reaches. Some items and passives turn Light Radius into other bonuses." },
  "energy-shield": { name: "Energy Shield", kind: "stat", status: "unchanged",
    statusNote: "No broad change in 3.30.", aliases: [],
    def: "A blue layer of protection over your life. Most damage hits it first. If you avoid damage for a short time, it starts to recharge on its own." },
  "resistance": { name: "Resistance", kind: "stat", status: "unchanged",
    statusNote: "No change for you. Hired Mercenaries now get resistance penalties.",
    aliases: ["Resistances", "Elemental Resistances", "Elemental Resistance", "Chaos Resistance"],
    def: "Cuts the fire, cold, lightning or chaos damage you take by a percentage, usually up to 75%. The campaign lowers your resistances as you go, so you need gear to make up for it." },
  "leech": { name: "Leech", kind: "stat", status: "unchanged",
    statusNote: "No broad change. Atziri's Acuity now makes crit leech instant.", aliases: ["Life Leech", "Leeched"],
    def: "Healing from the damage you deal. A part of each hit flows back to you as life or mana over a short time." },
  "recoup": { name: "Recoup", kind: "stat", status: "unchanged",
    statusNote: "No broad change. Shavronne's Wrappings now has it.", aliases: ["Recouped"],
    def: "Getting back part of the damage you take. A share of each hit refills your life, mana or Energy Shield over the next few seconds." },
  "impale": { name: "Impale", kind: "stat", status: "unchanged",
    statusNote: "No broad change. Steelworm now adds Impale effect.", aliases: [],
    def: "A physical attack effect. An impaled enemy takes extra damage from your next few hits, based on the hit that impaled it." },
  "arcane-might": { name: "Arcane Might", kind: "stat", status: "unchanged",
    statusNote: "Mercenary Kinetic Blast now has 150%, matching the player's.", aliases: [],
    def: "A skill keyword since 3.29. Bonuses to spell damage also boost the skill's attack damage, at a set share of their value, such as 150%." },
  "bark": { name: "Bark", kind: "stat", status: "changed",
    statusNote: "Warden passives make Bark regrow faster and stop more damage.", aliases: ["Barkskin"],
    def: "Stacks from the Warden's Barkskin skill, up to 10. Each Bark cuts the damage you take from hits. Each attack that hits you strips one, and they regrow while you aren't hit." },
  "thorns": { name: "Thorns", kind: "stat", status: "unchanged",
    statusNote: "No change in 3.30. Reflect map modifiers have given rare monsters Thorns since 3.29.",
    aliases: ["Physical Thorns", "Elemental Thorns"],
    def: "Damage that hits back at whoever strikes. Since 3.29, rare monsters in reflect maps gain Thorns for 5 seconds after you hit them, and each hit you land costs you a fixed amount." },
  "reflect": { name: "Reflect", kind: "stat", status: "changed",
    statusNote: "Atziri no longer reflects damage, and her mirror clone reflects 15%, down from 100%.", aliases: ["reflects"],
    def: "Sending part of the damage a monster takes back at the attacker. Reflect map modifiers used to do this to you. Since 3.29 they give rare monsters Thorns instead." },
  "pack-size": { name: "Pack Size", kind: "stat", status: "unchanged",
    statusNote: "Some Temple of Atzoatl rooms now add Pack Size.", aliases: ["pack size", "Monster Pack Size"],
    def: "A bonus for more monsters in each group in an area. More monsters means more loot and experience, and more danger." },

  /* Bosses */

  "atziri": { name: "Atziri", kind: "boss", status: "changed",
    statusNote: "Moves into the Temple of Atzoatl, and her fight is reworked.", aliases: ["Alluring Abyss"],
    def: "The queen of the ancient Vaal empire and a long-running endgame boss. Since 3.30 she lives in the Temple of Atzoatl, her fight is reworked, and the Alluring Abyss, home of her harder fight, is gone." },
  "maven": { name: "Maven", kind: "boss", status: "changed",
    statusNote: "Beating her now gives 2 Atlas skill points.", aliases: [],
    def: "A top endgame boss who collects other bosses. Her Invitations open fights against several of them at once." },
  "searing-exarch": { name: "Searing Exarch", kind: "boss", status: "changed",
    statusNote: "Its altars can drop Threads, and beating it gives 2 Atlas skill points.", aliases: [],
    def: "One of the two Eldritch bosses, top endgame bosses you work toward through altars in your maps. The other is the Eater of Worlds." },
  "eater-of-worlds": { name: "Eater of Worlds", kind: "boss", status: "changed",
    statusNote: "Its altars can drop Threads, and beating it gives 2 Atlas skill points.", aliases: [],
    def: "One of the two Eldritch bosses, top endgame bosses you work toward through altars in your maps. The other is the Searing Exarch." },
  "pinnacle-boss": { name: "Pinnacle boss", kind: "boss", status: "changed",
    statusNote: "Four Cortex bosses now count as pinnacle bosses, and most pinnacle items get their own sound.",
    aliases: ["Pinnacle", "Uber Atziri", "Uber Elder", "Uber"],
    def: "The hardest endgame bosses, like the Maven, the Searing Exarch and the Eater of Worlds. Uber versions are even harder, with better loot." },
  "map-boss": { name: "Map Boss", kind: "boss", status: "changed",
    statusNote: "Divine Vessels can Deify a map to make its boss stronger and richer.", aliases: ["Map Bosses"],
    def: "The boss at the end of a map. Killing it usually completes the map." },
  "saresh": { name: "Saresh", kind: "boss", status: "changed",
    statusNote: "The fight is much harder, and Saresh no longer drops a Mirage map.", aliases: [],
    def: "The necromancer who leads the villains of the 3.28 Mirage league. You fight Saresh in the Black Barya." },
  "vaal-omnitect": { name: "Vaal Omnitect", kind: "boss", status: "removed",
    statusNote: "Atziri evicts it from the Temple in 3.30.", aliases: ["Omnitect"],
    def: "The old final boss of the Temple of Atzoatl, the Vaal temple built through Incursions. Atziri takes its place in 3.30." },
  "architect": { name: "Architect", kind: "boss", status: "changed",
    statusNote: "Xipocado gets a new title and appears in Alluring Incursions.",
    aliases: ["Architects", "Incursion Architect", "Xipocado"],
    def: "A named Vaal boss tied to one room of the Temple of Atzoatl. You meet Architects during Incursions and inside the Temple itself." },
  "trialmaster": { name: "Trialmaster", kind: "boss", status: "changed",
    statusNote: "Now drops Ambition, a unique Vaal Aspect.", aliases: [],
    def: "The host of Ultimatum, the trial mini-game. Now and then he takes the place of a trial's final round and fights you himself, as a boss with his own drops." },
  "incarnation": { name: "Incarnation", kind: "boss", status: "unchanged",
    statusNote: "No change in 3.30.", aliases: ["Incarnations"],
    def: "A top endgame boss at the end of a Memory Trace, a chain of maps on the Atlas. There are three: the Incarnations of Fear, Neglect and Dread." },

  /* Characters */

  "kirac": { name: "Kirac", kind: "npc", status: "changed",
    statusNote: "Sells Unique Maps more often, and his prices move off Orbs of Chance.", aliases: [],
    def: "The endgame helper who runs a shop of maps and map items, which you can reroll with Gold. He also gives you Maven Invitations." },
  "whakano": { name: "Whakano", kind: "npc", status: "changed",
    statusNote: "Now sells Contracts and Blueprints for Gold, and grants bonus reveals.", aliases: [],
    def: "A Heist character in the Rogue Harbour, the thieves' base. He sells Contracts and reveals Blueprint wings for Rogue Markers, Heist's coins." },
  "syndicate": { name: "Immortal Syndicate", kind: "npc", status: "changed",
    statusNote: "Safehouse rewards are reworked. Scarab chests now hold uniques, Embers or Threads.",
    aliases: ["Syndicate", "Safehouse", "Safehouses", "Catarina", "Vorici", "Riker", "Elreon", "Rin"],
    def: "The gang of rivals in Betrayal, led by Catarina. You fight its members in maps and raid their hideouts, called Safehouses, for rewards." },
  "afarud": { name: "Afarud", kind: "npc", status: "changed",
    statusNote: "Afarud Rogue Exiles lose their Infamous drops, and a new Afarud crystal arrives.", aliases: [],
    def: "The villains of the 3.28 Mirage league, a twisted sect who trap and drain Djinn, magical spirits. Their soldiers and generals appear in Mirage content." },
  "maraketh": { name: "Maraketh", kind: "npc", status: "changed",
    statusNote: "Restored Maraketh uniques can now drop inside Mirages.", aliases: [],
    def: "A desert people of Wraeclast. In the 3.28 Mirage story, the Afarud twisted Maraketh unique items, and a coin could restore them. Since 3.30 the restored ones can drop inside Mirages." },
  "covenite": { name: "Covenite", kind: "npc", status: "new",
    statusNote: "New in 3.30, the enemies of Covens of Umbra.", aliases: ["covenites", "Covenites", "covenite"],
    def: "A member of the Coven, the 3.30 league's enemies. Covenites perform gruesome rites to summon their Queen. Defeat them to break a rite, then pick a Fate that makes the area's boss harder and richer." },

  /* Skills and build words */

  "skill-gem": { name: "Skill Gem", kind: "skill", status: "changed",
    statusNote: "Several skill gems are rebalanced, and their vendor prices change.", aliases: ["Skill Gems", "Skills Gems", "Gem", "Gems"],
    def: "A gem you put in a gear socket to gain an active skill, like Fireball. It levels up as you gain experience." },
  "support-gem": { name: "Support Gem", kind: "skill", status: "changed",
    statusNote: "Transfusion and Vaal Sacrifice change, plus several supports on Mercenaries.",
    aliases: ["Support Gems", "Support", "Supports"],
    def: "A gem linked to a skill gem that changes how that skill works, such as adding projectiles. Exceptional Support Gems are rarer, stronger endgame versions." },
  "exceptional-gem": { name: "Exceptional gem", kind: "skill", status: "unchanged",
    statusNote: "Transfusion can now come from cards that give random Exceptional Support Gems.",
    aliases: ["Exceptional Support Gems", "Exceptional Support Gem", "Exceptional Skill Gem", "Exceptional Skill Gems", "Exceptional Gem"],
    def: "A rare, stronger kind of skill or support gem, found in the endgame since 3.28. Pact of Beidat and Transfusion are examples." },
  "vaal-skill-gem": { name: "Vaal skill gem", kind: "skill", status: "unchanged",
    statusNote: "The Vaal Orb vendor recipe now takes 5 of them.", aliases: ["Vaal Skill Gems", "Vaal Skill Gem", "Vaal skill gems"],
    def: "A skill gem with a second, stronger Vaal version of its skill. You charge the Vaal skill with souls from monsters you kill, then use it for a burst of power." },
  "scion": { name: "Scion", kind: "skill", status: "unchanged",
    statusNote: "The class is the same. Her Reliquarian and Luminary ascendancies change.", aliases: [],
    def: "A character class who starts in the middle of the passive skill tree, so she can reach any part of it. Since 3.29 every account can make one from the start." },
  "transfigured-gem": { name: "Transfigured Gem", kind: "skill", status: "changed",
    statusNote: "3.30 adds Fireball of Radiation.",
    aliases: ["Transfigured Gems", "Transfigured Skill", "Transfigured Skill Gem", "Fireball of Radiation"],
    def: "An alternate version of a skill gem that works in a new way. Fireball of Radiation, new in 3.30, adds a short, strong burn around the fireball." },
  "link-skill": { name: "Link Skill", kind: "skill", status: "changed",
    statusNote: "Flame Link changes, and the new Arcane Link joins them.", aliases: ["Link Skills", "Flame Link"],
    def: "A skill that tethers you to an ally, like another player or a minion, to give them a buff while linked. Flame Link is one example." },
  "golem": { name: "Golem", kind: "skill", status: "changed",
    statusNote: "Flame, Lightning and Stone Golems give smaller bonuses.", aliases: ["Golems"],
    def: "A minion you summon with a Summon Golem skill. Besides fighting, each golem gives you a bonus, such as more damage or defences." },
  "minion": { name: "Minion", kind: "skill", status: "unchanged",
    statusNote: "No broad change in 3.30.",
    aliases: ["Minions", "Raised Spectre", "Raised Spectres", "Summoned Skeleton", "Summoned Skeletons", "Raised Zombie", "Raised Zombies", "raised Zombie", "Summoned Raging Spirit"],
    def: "A creature that fights for you, such as a Skeleton, Zombie, Spectre or Golem. You summon or raise them with skills." },
  "arcane-link": { name: "Arcane Link", kind: "skill", status: "new",
    statusNote: "New Intelligence skill in 3.30.", aliases: [],
    def: "A new link skill. It ties you to an allied player, giving them extra lightning damage based on your mana. If they die while linked, you die too." },
  "ascendancy": { name: "Ascendancy", kind: "skill", status: "changed",
    statusNote: "Five ascendancies get passive changes in 3.30.", aliases: ["Ascendancy Class", "Ascendancies"],
    def: "A subclass for your character, unlocked by clearing the Labyrinth, a trap-filled dungeon. It adds a small tree of strong passive skills." },
  "reliquarian": { name: "Reliquarian", kind: "skill", status: "changed",
    statusNote: "Its notable passives are shuffled for Covens of Umbra.", aliases: [],
    def: "A Scion ascendancy added in 3.28. Its passives copy powers from unique items, and the set changes every league." },
  "luminary": { name: "Luminary", kind: "skill", status: "changed",
    statusNote: "Golden Glory's Light Radius bonus to Mercenary buffs is halved.", aliases: ["Luminaries"],
    def: "A Scion ascendancy added in 3.29. It can keep up to three hired Mercenaries, fighters you duel and recruit, and change the gear they wear." },
  "pathfinder": { name: "Pathfinder", kind: "skill", status: "changed",
    statusNote: "Three flask passives change.", aliases: [],
    def: "A Ranger ascendancy built around flasks, the refillable potions on your belt." },
  "warden": { name: "Warden", kind: "skill", status: "changed",
    statusNote: "Five passives get stronger.", aliases: [],
    def: "A Ranger ascendancy built around Tinctures, flask-like weapon boosts, and Bark, stacks that cut the damage you take and regrow when you aren't being hit." },
  "trickster": { name: "Trickster", kind: "skill", status: "changed",
    statusNote: "Three passives get stronger.", aliases: [],
    def: "A Shadow ascendancy with a mix of defences, such as evasion and Energy Shield, plus bonuses for speed and damage over time." },
  "keystone": { name: "Keystone", kind: "skill", status: "changed",
    statusNote: "Six Atlas keystones are removed and one is added.", aliases: ["Keystones", "Atlas Keystone Passive"],
    def: "A big passive skill that changes a rule of the game, often with a drawback. Both your character's tree and the Atlas Passive Tree have them." },
  "notable-passive": { name: "Notable Passive", kind: "skill", status: "changed",
    statusNote: "Many notables, mostly on ascendancies, change in 3.30.",
    aliases: ["Notable Passives", "Notable Passive Skill", "Notable Passive Skills", "Notables", "Notable"],
    def: "A larger, named passive skill with a stronger bonus than the small passives around it." }

});
